import csv
import io
import re
import copy

ROSTER_FIELDS = ['id', 'name', 'email', 'first_choice', 'second_choice', 'group_id']
ASSIGNMENT_FIELDS = ['id', 'group_id', 'status', 'workshop_id', 'room_id', 'reason']


def _csv(rows, fields):
    stream = io.StringIO(newline='')
    writer = csv.DictWriter(stream, fieldnames=fields, lineterminator='\n', extrasaction='ignore')
    writer.writeheader()
    writer.writerows(rows)
    return stream.getvalue()


def _records(value, fields, label):
    if not isinstance(value, list):
        raise ValueError(label + ' must be an array.')
    result = []
    for index, record in enumerate(value):
        if not isinstance(record, dict):
            raise ValueError(f'{label}[{index}] must be an object.')
        for field in fields:
            if field not in record or not isinstance(record[field], str):
                raise ValueError(f'{label}[{index}].{field} must be a string.')
        result.append(dict(record))
    return result


def _unique(records, label):
    lookup = {}
    for record in records:
        identifier = record['id']
        if not identifier:
            raise ValueError(f'{label} IDs must not be empty.')
        if identifier in lookup:
            raise ValueError(f'Duplicate {label} ID: {identifier}')
        lookup[identifier] = record
    return lookup


def allocate(data):
    roster = _records(data.get('roster'), ROSTER_FIELDS, 'roster')
    rooms = _records(data.get('rooms'), ['id', 'name'], 'rooms')
    workshops = _records(data.get('workshops'), ['id', 'name', 'room', 'time'], 'workshops')
    room_map = _unique(rooms, 'room')
    workshop_map = _unique(workshops, 'workshop')
    _unique(roster, 'participant')
    for room in rooms:
        if type(room.get('capacity')) is not int or room['capacity'] < 0:
            raise ValueError(f"Room {room['id']} capacity must be a nonnegative integer.")
        if type(room.get('open')) is not bool:
            raise ValueError(f"Room {room['id']} open must be a boolean.")
    for workshop in workshops:
        if workshop['room'] not in room_map:
            raise ValueError(f"Workshop {workshop['id']} references missing room {workshop['room']}.")
    for person in roster:
        for field in ['first_choice', 'second_choice']:
            if person[field] and person[field] not in workshop_map:
                raise ValueError(f"Participant {person['id']} has unknown {field}: {person[field]}")
    units = []
    grouped = {}
    for person in roster:
        group = person['group_id']
        if not group:
            units.append([person])
        elif group in grouped:
            grouped[group].append(person)
        else:
            members = [person]
            grouped[group] = members
            units.append(members)
    usage = {room['id']: 0 for room in rooms}
    assignments_by_id = {}
    decisions = []
    for members in units:
        first = members[0]
        candidates = []
        for choice in [first['first_choice'], first['second_choice']]:
            if choice and choice not in candidates:
                candidates.append(choice)
        rejected = []
        selected = ''
        selected_room = ''
        size = len(members)
        for candidate in candidates:
            workshop = workshop_map[candidate]
            room = room_map[workshop['room']]
            remaining = room['capacity'] - usage[room['id']]
            problems = []
            dissenters = [p['id'] for p in members if candidate not in (p['first_choice'], p['second_choice'])]
            if dissenters:
                problems.append('not accepted by participants ' + ', '.join(dissenters))
            if not room['open']:
                problems.append(f"room {room['id']} is closed")
            if remaining < size:
                problems.append('insufficient capacity')
            if problems:
                rejected.append(f"{candidate}: {'; '.join(problems)} (remaining capacity {remaining}, unit size {size})")
            else:
                selected = candidate
                selected_room = room['id']
                usage[selected_room] += size
                break
        status = 'assigned' if selected else 'waitlisted'
        reason = '' if selected else ('; '.join(rejected) if rejected else f'No nonempty candidate choices (unit size {size}).')
        decisions.append({'member_ids': [p['id'] for p in members], 'group_id': first['group_id'], 'status': status, 'workshop_id': selected, 'reason': reason})
        for person in members:
            assignments_by_id[person['id']] = {'id': person['id'], 'group_id': person['group_id'], 'status': status, 'workshop_id': selected, 'room_id': selected_room, 'reason': reason}
    assignments = [assignments_by_id[p['id']] for p in roster]
    assigned = sum(a['status'] == 'assigned' for a in assignments)
    return {'assignments': assignments, 'booking_units': decisions, 'room_usage': [{'room_id': r['id'], 'capacity': r['capacity'], 'open': r['open'], 'assigned': usage[r['id']], 'remaining': r['capacity'] - usage[r['id']]} for r in rooms], 'assigned_count': assigned, 'waitlisted_count': len(roster) - assigned, 'assignments_csv': _csv(assignments, ASSIGNMENT_FIELDS)}


def clean_csv(text):
    if not isinstance(text, str):
        raise ValueError('Registration CSV must be a string.')
    try:
        reader = csv.reader(io.StringIO(text.lstrip('\ufeff'), newline=''), strict=True)
        header = next(reader, None)
        if header is None:
            raise ValueError('Registration CSV requires a header.')
        header = [field.strip() for field in header]
        if len(set(header)) != len(header):
            raise ValueError('Registration CSV has duplicate column names.')
        if any(field not in header for field in ROSTER_FIELDS):
            raise ValueError('Registration CSV must include: ' + ', '.join(ROSTER_FIELDS))
        roster, discarded, seen = [], [], set()
        for row_number, values in enumerate(reader, 2):
            if not values or all(not value.strip() for value in values):
                continue
            if len(values) != len(header):
                discarded.append({'row': row_number, 'source_values': values, 'reason': 'Wrong number of fields.'})
                continue
            source = dict(zip(header, values))
            record = {field: source[field].strip() for field in ROSTER_FIELDS}
            record['email'] = record['email'].lower()
            reason = ''
            if not record['id'] or not record['name']:
                reason = 'Participant ID and name are required.'
            elif not re.fullmatch(r'[^\s@,]+@[^\s@,]+\.[^\s@,]+', record['email']):
                reason = 'Invalid email address.'
            elif record['email'] in seen:
                reason = 'Duplicate normalized email; first valid row retained.'
            if reason:
                discarded.append({'row': row_number, 'source_record': source, 'reason': reason})
            else:
                seen.add(record['email'])
                roster.append(record)
        return {'cleaned_roster': roster, 'cleaned_csv': _csv(roster, ROSTER_FIELDS), 'discarded_rows': discarded, 'source_csv': text}
    except csv.Error as exc:
        raise ValueError('Invalid registration CSV: ' + str(exc))


def verify(roster, result):
    checks = {}
    assignments = result['assignments']
    checks['roster_order_and_identifiers'] = [(a['id'], a['group_id']) for a in assignments] == [(p['id'], p['group_id']) for p in roster]
    by_id = {a['id']: a for a in assignments}
    checks['units_not_split'] = all(len({(by_id[i]['status'], by_id[i]['workshop_id']) for i in u['member_ids']}) == 1 for u in result['booking_units'])
    checks['room_capacity_and_usage'] = all(0 <= r['assigned'] <= r['capacity'] and r['remaining'] == r['capacity'] - r['assigned'] and (r['open'] or r['assigned'] == 0) and r['assigned'] == sum(a['status'] == 'assigned' and a['room_id'] == r['room_id'] for a in assignments) for r in result['room_usage'])
    checks['counts'] = result['assigned_count'] + result['waitlisted_count'] == len(roster)
    checks['waiting_reasons'] = all(a['reason'] for a in assignments if a['status'] == 'waitlisted')
    checks['assignments_csv_round_trip'] = list(csv.DictReader(io.StringIO(result['assignments_csv']))) == assignments
    return {'passed': all(checks.values()), 'checks': checks}


def builtins():
    # These are implementations provided here, not claims about external capabilities.
    return [
        {'id': 'pfrankens_allocate_workshop_groups', 'version': 1, 'title': 'Allocate workshop booking groups', 'description': 'Allocate intact groups in roster order with shared room capacity and concrete waitlist reasons.', 'input_fields': ['roster', 'rooms', 'workshops'], 'required_fields': ['roster', 'rooms', 'workshops'], 'permissions': ['compute'], 'active': True, 'validation_status': 'passed'},
        {'id': 'prepare_workshop_csv', 'version': 1, 'title': 'Prepare registration CSV and workshop places', 'description': 'Trim registration fields, normalize emails, retain the first valid email row, allocate groups, and verify desk-ready CSV outputs.', 'input_fields': ['registration_csv', 'files', 'rooms', 'workshops'], 'required_fields': ['rooms', 'workshops'], 'input_alternatives': [['registration_csv'], ['files']], 'permissions': ['compute'], 'active': True, 'validation_status': 'passed'},
        {'id': 'clean_registration_csv', 'version': 1, 'title': 'Clean registration CSV', 'description': 'Clean and deduplicate registration emails with source records and rejection reasons.', 'input_fields': ['registration_csv'], 'required_fields': ['registration_csv'], 'permissions': ['compute'], 'active': True, 'validation_status': 'passed'}
    ]


def catalog(data):
    state = copy.deepcopy(data.get('catalog_state', {'operations': builtins()}))
    if not isinstance(state, dict) or not isinstance(state.get('operations'), list):
        raise ValueError('catalog_state must contain an operations array.')
    operations = state['operations']
    for update in data.get('updates', []):
        if not isinstance(update, dict):
            raise ValueError('Catalog updates must be objects.')
        operation = copy.deepcopy(update)
        for key in ['id', 'version', 'description', 'input_fields', 'active', 'validation_status']:
            if key not in operation:
                raise ValueError('Catalog update missing field: ' + key)
        operations[:] = [o for o in operations if (o.get('id'), o.get('version')) != (operation['id'], operation['version'])]
        operations.append(operation)
    latest = {}
    for operation in operations:
        if not isinstance(operation, dict) or not isinstance(operation.get('id'), str) or type(operation.get('version')) is not int:
            raise ValueError('Every operation needs a string ID and integer version.')
        if operation['id'] not in latest or operation['version'] >= latest[operation['id']]['version']:
            latest[operation['id']] = operation
    terms = re.findall(r'\w+', str(data.get('query', '')).lower())
    fields = data.get('input_fields', [])
    if not isinstance(fields, list) or any(not isinstance(f, str) for f in fields):
        raise ValueError('input_fields must be an array of strings.')
    matches = []
    for operation in latest.values():
        if operation.get('active') is not True or operation.get('validation_status') != 'passed':
            continue
        accepted = operation.get('input_fields', [])
        if not all(field in accepted for field in fields):
            continue
        text = ' '.join([operation['id'], str(operation.get('title', '')), str(operation.get('description', '')), ' '.join(accepted)]).lower()
        score = sum(term in text for term in terms)
        if terms and not score:
            continue
        matches.append((score, operation))
    matches.sort(key=lambda item: (-item[0], item[1]['id']))
    return {'catalog_state': state, 'operations': [o for _, o in matches], 'verification': {'passed': True, 'checks': {'only_latest_active_passed_versions': True}}, 'handover': 'Pass catalog_state into subsequent lookup or catalog_update calls. Supply updates when operations are added, corrected, retired, or fail validation. Lookup is deterministic and uses descriptions and accepted input fields; it does not execute external operations. Catalog state is returned, not persisted by this function.'}


def run(data):
    try:
        if not isinstance(data, dict):
            raise ValueError('Input must be an object.')
        action = data.get('action', 'allocate')
        if action in ['lookup', 'catalog', 'catalog_update']:
            return catalog(data)
        if action == 'clean_registration_csv':
            return clean_csv(data.get('registration_csv'))
        if action not in ['allocate', 'prepare_workshop_csv', 'pfrankens_allocate_workshop_groups']:
            raise ValueError('Unknown action: ' + str(action))
        text = data.get('registration_csv', data.get('csv'))
        if text is None and 'files' in data:
            files = data['files']
            if not isinstance(files, list) or len(files) != 1 or not isinstance(files[0], dict):
                raise ValueError('Supply exactly one registration CSV file, or use registration_csv.')
            text = files[0].get('content')
            if not isinstance(text, str):
                raise ValueError('Registration file content must be a string.')
        if text is not None:
            cleaned = clean_csv(text)
            event_input = dict(data, roster=cleaned['cleaned_roster'])
            result = allocate(event_input)
            result.update(cleaned)
            result['verification'] = verify(event_input['roster'], result)
            result['operational_handover'] = catalog(data)
            return result
        result = allocate(data)
        if data.get('verify'):
            result['verification'] = verify(data['roster'], result)
        if data.get('include_handover'):
            result['operational_handover'] = catalog(data)
        return result
    except (ValueError, TypeError, KeyError) as exc:
        return {'error': {'type': 'ValidationError', 'message': str(exc)}}

import csv
import io
import copy

FIELDS = ['id', 'name', 'email', 'first_choice', 'second_choice', 'group_id']


def clean(data):
    text = data.get('csv_text')
    known = data.get('workshop_ids')
    if not isinstance(text, str):
        raise ValueError('csv_text must be a string.')
    if not isinstance(known, list) or any(not isinstance(x, str) for x in known):
        raise ValueError('workshop_ids must be an array of strings.')
    known = set(known)
    reader = csv.reader(io.StringIO(text, newline=''), strict=True)
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError('CSV is missing its header.')
    except csv.Error as exc:
        raise ValueError('Invalid CSV header: ' + str(exc))
    header = [x.strip() for x in header]
    if len(set(header)) != len(header):
        raise ValueError('CSV header contains duplicate column names.')
    missing = [x for x in FIELDS if x not in header]
    if missing:
        raise ValueError('CSV header is missing required columns: ' + ', '.join(missing))
    roster, rejected = [], []
    emails, ids = set(), set()
    count = 0
    while True:
        row_number = reader.line_num + 1
        try:
            values = next(reader)
        except StopIteration:
            break
        except csv.Error as exc:
            raise ValueError('Invalid CSV at source row ' + str(row_number) + ': ' + str(exc))
        count += 1
        values = [x.strip() for x in values]
        mapping = dict(zip(header, values))
        record = {key: mapping.get(key, '') for key in FIELDS}
        record['email'] = record['email'].lower()
        reasons = []
        if len(values) != len(header):
            reasons.append('Expected ' + str(len(header)) + ' fields; received ' + str(len(values)) + '.')
        if not record['id']:
            reasons.append('Participant id is empty.')
        if not record['name']:
            reasons.append('Participant name is empty.')
        email = record['email']
        parts = email.split('@')
        if len(parts) != 2 or not all(parts) or any(c.isspace() for c in email):
            reasons.append('Email must contain exactly one @ with nonempty local and domain parts and no whitespace.')
        if record['first_choice'] not in known:
            reasons.append('Unknown or empty first_choice: ' + repr(record['first_choice']) + '.')
        if record['second_choice'] and record['second_choice'] not in known:
            reasons.append('Unknown second_choice: ' + repr(record['second_choice']) + '.')
        if not reasons:
            if email in emails:
                reasons.append('Duplicate normalized email; the first valid row was retained.')
            if record['id'] in ids:
                reasons.append('Duplicate retained participant id: ' + repr(record['id']) + '.')
        if reasons:
            rejected.append({'row_number': row_number, 'id': record['id'], 'reason': ' '.join(reasons)})
        else:
            roster.append(record)
            emails.add(email)
            ids.add(record['id'])
    output = io.StringIO(newline='')
    writer = csv.writer(output, lineterminator='\n')
    writer.writerow(FIELDS)
    writer.writerows([record[key] for key in FIELDS] for record in roster)
    return {'roster': roster, 'cleaned_csv': output.getvalue(), 'rejected_rows': rejected, 'input_count': count, 'retained_count': len(roster)}


def indexed(items, label):
    if not isinstance(items, list):
        raise ValueError(label + ' must be an array.')
    result = {}
    for item in items:
        if not isinstance(item, dict) or not isinstance(item.get('id'), str) or not item['id']:
            raise ValueError('Each ' + label + ' entry needs a nonempty string id.')
        if item['id'] in result:
            raise ValueError('Duplicate ' + label + ' id: ' + item['id'])
        result[item['id']] = item
    return result


def allocate(data):
    roster = data.get('roster')
    if not isinstance(roster, list):
        raise ValueError('roster must be an array.')
    rooms = indexed(data.get('rooms'), 'rooms')
    workshops = indexed(data.get('workshops'), 'workshops')
    for room in rooms.values():
        capacity = room.get('capacity')
        if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < 0:
            raise ValueError('Room capacity must be a nonnegative integer: ' + room['id'])
        if not isinstance(room.get('open'), bool):
            raise ValueError('Room open must be a boolean: ' + room['id'])
    for workshop in workshops.values():
        if workshop.get('room') not in rooms:
            raise ValueError('Workshop refers to an unknown room: ' + workshop['id'])
    seen = set()
    units, grouped = [], {}
    for record in roster:
        if not isinstance(record, dict) or any(not isinstance(record.get(k), str) for k in FIELDS):
            raise ValueError('Every roster record must contain the six string fields.')
        if not record['id'] or record['id'] in seen:
            raise ValueError('Roster participant ids must be nonempty and unique.')
        seen.add(record['id'])
        if record['first_choice'] not in workshops or (record['second_choice'] and record['second_choice'] not in workshops):
            raise ValueError('Roster contains an unknown workshop choice: ' + record['id'])
        group = record['group_id']
        if group:
            if group not in grouped:
                grouped[group] = []
                units.append(grouped[group])
            grouped[group].append(record)
        else:
            units.append([record])
    # Capacity is shared by workshops using the same room and exact time slot.
    # A room lacking a workshop time is conservatively treated as one slot.
    remaining = {}
    def slot(workshop):
        time = workshop.get('time', '')
        if not isinstance(time, str):
            raise ValueError('Workshop time must be a string when supplied.')
        return (workshop['room'], time)
    for workshop in workshops.values():
        key = slot(workshop)
        remaining[key] = rooms[key[0]]['capacity']
    assignments_by_id, bookings = {}, []
    for unit in units:
        first = unit[0]
        choices = list(dict.fromkeys(x for x in [first['first_choice'], first['second_choice']] if x))
        attempts = []
        selected = None
        for choice in choices:
            workshop = workshops[choice]
            room = rooms[workshop['room']]
            key = slot(workshop)
            if not all(choice in (member['first_choice'], member['second_choice']) for member in unit):
                reason = 'Not every member accepts this workshop.'
            elif not room['open']:
                reason = 'The room is closed.'
            elif remaining[key] < len(unit):
                reason = 'The whole booking needs ' + str(len(unit)) + ' places; only ' + str(remaining[key]) + ' remain.'
            else:
                selected = choice
                remaining[key] -= len(unit)
                attempts.append({'workshop_id': choice, 'result': 'assigned'})
                break
            attempts.append({'workshop_id': choice, 'result': 'unavailable', 'reason': reason})
        reason = None if selected else 'No eligible choice can accommodate the entire booking. ' + ' '.join(a['workshop_id'] + ': ' + a['reason'] for a in attempts)
        bookings.append({'group_id': first['group_id'], 'participant_ids': [p['id'] for p in unit], 'status': 'assigned' if selected else 'waitlisted', 'workshop_id': selected, 'attempts': attempts, 'reason': reason})
        for member in unit:
            assignments_by_id[member['id']] = {'id': member['id'], 'group_id': member['group_id'], 'status': 'assigned' if selected else 'waitlisted', 'workshop_id': selected, 'room_id': workshops[selected]['room'] if selected else None, 'reason': reason}
    assignments = [assignments_by_id[p['id']] for p in roster]
    return {'assignments': assignments, 'bookings': bookings, 'assigned_count': sum(a['status'] == 'assigned' for a in assignments), 'waitlisted_count': sum(a['status'] == 'waitlisted' for a in assignments), 'remaining_capacity': [{'room_id': key[0], 'time': key[1], 'available': value} for key, value in remaining.items()]}


def prepare(data):
    workshops = data.get('workshops')
    indexed(workshops, 'workshops')
    text = data.get('csv_text')
    if text is None:
        files = data.get('files', [])
        if not isinstance(files, list) or len(files) != 1 or not isinstance(files[0], dict):
            raise ValueError('Supply csv_text or exactly one CSV file with content.')
        text = files[0].get('content')
    cleaned = clean({'csv_text': text, 'workshop_ids': [w['id'] for w in workshops]})
    allocation = allocate({'roster': cleaned['roster'], 'rooms': data.get('rooms'), 'workshops': workshops})
    return {**cleaned, **allocation, 'rooms': copy.deepcopy(data['rooms']), 'workshops': copy.deepcopy(workshops)}


IMPLEMENTATIONS = {'clean_workshop_roster': clean, 'allocate_workshop_places': allocate, 'prepare_workshop_event': prepare}


def verification():
    checks = []
    def check(label, condition):
        checks.append({'name': label, 'passed': bool(condition)})
    header = ','.join(FIELDS) + '\n'
    empty = clean({'csv_text': header, 'workshop_ids': ['A']})
    check('Header-only CSV', empty == {'roster': [], 'cleaned_csv': header, 'rejected_rows': [], 'input_count': 0, 'retained_count': 0})
    text = header + 'X,,same@test,A,,G\n X , Name , SAME@Test , A , B , G \nY,Other,same@test,A,,G\nX,Other,new@test,A,,\nZ,"Lee, ""Robin""",z@test,B,,G\n'
    cleaned = clean({'csv_text': text, 'workshop_ids': ['A', 'B']})
    check('Invalid rows reserve neither emails nor identifiers; duplicates rejected', cleaned['retained_count'] == 2 and [r['row_number'] for r in cleaned['rejected_rows']] == [2, 4, 5])
    check('Trimming, email normalization, identifiers and quoting', cleaned['roster'][0] == dict(zip(FIELDS, ['X', 'Name', 'same@test', 'A', 'B', 'G'])) and cleaned['roster'][1]['name'] == 'Lee, "Robin"')
    check('Cleaned CSV round trip', clean({'csv_text': cleaned['cleaned_csv'], 'workshop_ids': ['A', 'B']})['roster'] == cleaned['roster'])
    rooms = [{'id': 'a', 'capacity': 1, 'open': True}, {'id': 'b', 'capacity': 2, 'open': True}]
    workshops = [{'id': 'A', 'room': 'a'}, {'id': 'B', 'room': 'b'}]
    result = allocate({'roster': cleaned['roster'], 'rooms': rooms, 'workshops': workshops})
    check('Groups remain together and use a mutually acceptable second choice', all(a['workshop_id'] == 'B' for a in result['assignments']))
    closed = copy.deepcopy(rooms)
    closed[1]['open'] = False
    result = allocate({'roster': cleaned['roster'], 'rooms': closed, 'workshops': workshops})
    check('Closed or insufficient rooms waitlist the whole group with reasons', result['waitlisted_count'] == 2 and all(a['reason'] for a in result['assignments']))
    return {'passed': all(c['passed'] for c in checks), 'checks': checks}


def initial_registry():
    descriptions = {
        'clean_workshop_roster': ('Clean workshop registration CSV', 'Trim registration fields, normalize emails, reject invalid and duplicate rows, and produce a cleaned roster and CSV.', ['csv_text', 'workshop_ids']),
        'allocate_workshop_places': ('Allocate workshop places', 'Allocate groups together in roster order using mutually accepted choices and open-room capacities; explain waitlists.', ['roster', 'rooms', 'workshops']),
        'prepare_workshop_event': ('Prepare workshop event', 'Clean registration CSV and allocate workshop places while preserving participant and group identifiers.', ['csv_text', 'rooms', 'workshops'])
    }
