def catalog(data):
    registry = copy.deepcopy(data.get('registry', initial_registry()))
    if not isinstance(registry, list):
        raise ValueError('registry must be an array of operation versions.')
    keys = set()
    for operation in registry:
        if not isinstance(operation, dict) or not isinstance(operation.get('id'), str) or not operation['id']:
            raise ValueError('Each operation needs a nonempty string id.')
        version = operation.get('version')
        if isinstance(version, bool) or not isinstance(version, int) or version < 1:
            raise ValueError('Operation versions must be positive integers.')
        key = (operation['id'], version)
        if key in keys:
            raise ValueError('Duplicate operation version.')
        keys.add(key)
    action = data.get('action', 'lookup')
    if action in ('register', 'update'):
        operation = copy.deepcopy(data.get('operation'))
        if not isinstance(operation, dict) or not isinstance(operation.get('id'), str) or not operation['id']:
            raise ValueError('operation needs a nonempty string id.')
        previous = [o for o in registry if o['id'] == operation['id']]
        if action == 'update' and not previous:
            raise ValueError('Cannot update an unknown operation.')
        merged = copy.deepcopy(max(previous, key=lambda o: o['version'])) if previous else {}
        merged.update(operation)
        merged['version'] = max([o['version'] for o in previous], default=0) + 1
        merged['status'] = operation.get('status', 'active')
        for old in previous:
            old['status'] = 'superseded'
        registry.append(merged)
    elif action == 'retire':
        matches = [o for o in registry if o['id'] == data.get('operation_id')]
        if not matches:
            raise ValueError('Cannot retire an unknown operation.')
        for operation in matches:
            operation['status'] = 'retired'
    elif action not in ('lookup', 'catalog', 'verify'):
        raise ValueError('Unknown catalog action: ' + str(action))
    tests = verification()
    for operation in registry:
        implementation = operation.get('implementation')
        schema = operation.get('input_schema')
        valid_schema = isinstance(schema, dict) and isinstance(schema.get('properties'), dict) and isinstance(schema.get('required', []), list)
        compatible = False
        if implementation in IMPLEMENTATIONS and valid_schema:
            base = next(o for o in initial_registry() if o['id'] == implementation)['input_schema']
            compatible = all(field in schema['properties'] for field in base['required']) and set(base['required']).issubset(schema.get('required', [])) and all(schema['properties'][field].get('type') == base['properties'][field]['type'] for field in base['required'] if isinstance(schema['properties'][field], dict)) and all(isinstance(schema['properties'][field], dict) for field in base['required'])
        operation['verification'] = {'passed': bool(tests['passed'] and compatible and operation.get('permissions') == ['compute']), 'reason': 'Verified supported implementation and compatible input schema.' if tests['passed'] and compatible and operation.get('permissions') == ['compute'] else 'Unsupported implementation, incompatible schema, permissions, or failed verification.'}
    latest = {}
    for operation in registry:
        if operation['id'] not in latest or operation['version'] > latest[operation['id']]['version']:
            latest[operation['id']] = operation
    query = data.get('query', '')
    fields = data.get('input_fields', [])
    if not isinstance(query, str) or not isinstance(fields, list) or any(not isinstance(x, str) for x in fields):
        raise ValueError('query must be a string and input_fields an array of strings.')
    terms = query.lower().split()
    matches = []
    for operation in latest.values():
        if operation.get('status') != 'active' or not operation['verification']['passed']:
            continue
        searchable = ' '.join(str(operation.get(k, '')) for k in ['id', 'title', 'description']).lower()
        if not all(term in searchable for term in terms):
            continue
        if not set(fields).issubset(operation['input_schema']['properties']):
            continue
        matches.append(copy.deepcopy(operation))
    return {'registry': registry, 'operations': matches, 'verification': tests, 'handover': {'description': 'Reusable operations are looked up deterministically by description keywords and accepted input fields. Only the latest active, verified version is recommended.', 'lookup_input': {'action': 'lookup', 'registry': 'Pass the registry returned by the previous call.', 'query': 'Description keywords, matched case-insensitively.', 'input_fields': 'Accepted field names to require.'}, 'lifecycle_actions': ['register', 'update', 'retire', 'verify'], 'registration': 'Supply operation metadata, a supported implementation, compatible input_schema, and permissions [compute]. Each update creates a new version and supersedes older versions. Unknown implementations are not recommended.', 'execution': 'Use action execute, operation_id, registry, and input. The registry is reverified before execution.', 'persistence': 'No live application or filesystem is accessed. Retain and pass the returned registry between calls to keep lifecycle changes current.'}}


def run(data):
    try:
        if not isinstance(data, dict):
            raise ValueError('Input must be an object.')
        action = data.get('action')
        if action in ('lookup', 'catalog', 'register', 'update', 'retire', 'verify'):
            return catalog(data)
        if action == 'execute':
            lookup = catalog({'registry': data.get('registry', initial_registry()), 'action': 'lookup'})
            matches = [o for o in lookup['operations'] if o['id'] == data.get('operation_id')]
            if len(matches) != 1:
                raise ValueError('Operation is unknown, inactive, superseded, or failed verification.')
            payload = data.get('input')
            if not isinstance(payload, dict):
                raise ValueError('input must be an object.')
            operation = matches[0]
            missing = [f for f in operation['input_schema']['required'] if f not in payload]
            if missing:
                raise ValueError('Missing operation inputs: ' + ', '.join(missing))
            return IMPLEMENTATIONS[operation['implementation']](payload)
        if action == 'allocate':
            return allocate(data)
        if action not in (None, 'clean', 'prepare'):
            raise ValueError('Unknown action: ' + str(action))
        if action == 'clean' or ('csv_text' in data and 'workshop_ids' in data and 'rooms' not in data and action != 'prepare'):
            return clean(data)
        event_input = data.get('data_sample', data)
        if isinstance(event_input, dict) and 'rooms' in event_input and 'workshops' in event_input:
            result = prepare(event_input)
            handover = catalog({'registry': data.get('registry', initial_registry()), 'action': 'lookup'})
            round_trip = clean({'csv_text': result['cleaned_csv'], 'workshop_ids': [w['id'] for w in event_input['workshops']]})
            checks = [{'name': 'Cleaned CSV round trip preserves retained roster', 'passed': round_trip['roster'] == result['roster']}, {'name': 'Every retained participant has exactly one assignment', 'passed': [a['id'] for a in result['assignments']] == [p['id'] for p in result['roster']]}, {'name': 'Capacity is never exceeded', 'passed': all(r['available'] >= 0 for r in result['remaining_capacity'])}, {'name': 'All waitlisted participants have concrete reasons', 'passed': all(a['reason'] for a in result['assignments'] if a['status'] == 'waitlisted')}]
            result['verification'] = {'passed': all(c['passed'] for c in checks) and handover['verification']['passed'], 'checks': checks, 'reusable_operation_tests': handover['verification']}
            result['operational_handover'] = handover
            return result
        return clean(data)
    except (ValueError, TypeError, KeyError, csv.Error) as exc:
        return {'error': str(exc)}

import re
import unicodedata


def _tokens(text):
    """Normalize case and accents; punctuation and underscores separate words."""
    normalized = unicodedata.normalize('NFKD', text.casefold())
    normalized = ''.join(
        char for char in normalized
        if not unicodedata.category(char).startswith('M')
    )
    return set(re.findall(r'[^\W_]+', normalized, flags=re.UNICODE))


def run(data):
    """Rebuild the compute-only catalog from the supplied current registry."""
    index = []
    for record in data['records']:
        if record['active'] is not True or record['tested'] is not True:
            continue
        if set(record['permissions']) != {'compute'}:
            continue

        terms = set()
        for text in (
            [record['id'], record['title'], record['description']]
            + record['input_fields']
            + record['output_fields']
        ):
            terms.update(_tokens(text))

        index.append({
            'id': record['id'],
            'version': record['version'],
            'terms': sorted(terms),
            'input_fields': list(record['input_fields']),
        })

    index.sort(key=lambda entry: entry['id'])
    required_inputs = set(data['required_inputs'])
    query = data['query']
    query_terms = _tokens(query)
    matches = set()
    for entry in index:
        if not required_inputs.issubset(entry['input_fields']):
            continue
        if query == '' or query_terms.intersection(entry['terms']):
            matches.add(entry['id'])

    return {'index': index, 'matches': sorted(matches)}
